  '@keyframes hop{0%,100%{transform:translateY(0)}40%{transform:translateY(-2px)}60%{transform:translateY(-2px)}}',
  '@keyframes blink{0%,94%,100%{transform:scaleY(1)}97%{transform:scaleY(.15)}}',
